set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {DatabaseSync} from 'node:sqlite';import {createRequire} from 'node:module';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const root='/var/lib/news-flow/qc-public24-20261123',require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),env=require('dotenv').parse(fs.readFileSync('/etc/news-flow/news.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:15000}),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:registry.allowedDomains,siteCooldown:false,maxWireRequests:8}),q=JSON.parse(fs.readFileSync(root+'/tieudungso-qualified.json')),readback=JSON.parse(fs.readFileSync(root+'/native-es-readback.json')),r={at:new Date().toISOString(),rows:[]},clean=s=>String(s||'').normalize('NFC').replace(/\s+/g,' ').trim();
try{for(const row of readback.tieudungso.filter(p=>p.mismatches.length===1&&p.mismatches[0]==='description')){const receipt=db.prepare('SELECT * FROM import_receipts WHERE id=?').get(row.id),hit=await es.get({index:receipt.es_index,type:receipt.es_type,id:receipt.es_id}),p=await driver.get('qc24-native-description-'+r.rows.length,row.url,registry.sources.get('tieudungso.vn').config,[],{reviewFailed:true,taskRole:'article'}),o={url:row.url,error:p.error,existingDescription:hit._source.description,apiDescription:q.pages.find(p=>p.url===row.url)?.doc?._source.description};if(p.html&&!p.error){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));const $=ch.load(p.html);o.nativeMeta=$('meta[name="description"],meta[property="og:description"],meta[name="twitter:description"]').toArray().map(e=>$(e).attr('content')).filter(Boolean);o.matchesNativeMeta=o.nativeMeta.some(s=>clean(s)===clean(o.existingDescription));o.matchesNativeBody=clean(hit._source.content).includes(clean(o.existingDescription));o.verified=o.matchesNativeMeta||o.matchesNativeBody;}r.rows.push(o);console.log(JSON.stringify(o));}r.verified=r.rows.length===5&&r.rows.every(p=>p.verified);r.combinedVerified=r.verified&&readback.tieudungso.every(p=>p.exactMatch||r.rows.some(v=>v.url===p.url&&v.verified))&&readback.cnn.every(p=>p.found&&p.proofMatched&&p.descriptionPresent);fs.writeFileSync(root+'/description-reconciliation.json',JSON.stringify(r,null,2));console.log(JSON.stringify({verified:r.verified,combinedVerified:r.combinedVerified}));}finally{db.close();es.close();await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-public24-20261123/description-reconciliation.json "$upload_dir/.qc-public24-description-reconciliation.json"
